// lint-staged loads a TypeScript config by importing the raw file, relying on Node's native type stripping, which is on by default from Node 23.6.0 and from 22.18.0 in the 22.x line.
import { defineConfig } from "lint-staged/config";

const eslintFix =
  "eslint --fix --cache --cache-location node_modules/.cache/eslint/.eslintcache";

export default defineConfig({
  "*.{ts,mts,md}": [eslintFix, "prettier --write --cache"],
  "*.json": [eslintFix, "prettier --write --cache"],
  // pnpm-lock.yaml is generated by pnpm and not meant to be reformatted by prettier.
  "!(pnpm-lock).{yml,yaml}": "prettier --write --cache",
});
